void check(bool value,const std::string& error){if(!value)throw std::runtime_error(error);}
AnimationMarkers marker_track(int start,int end,const std::vector<std::pair<int,std::string>>& markers){std::vector<std::uint8_t> times(markers.size()*4);std::vector<const char*> names(markers.size());std::vector<dh2::animation::EventGroup> groups(markers.size());for(std::size_t i=0;i<markers.size();++i){const auto value=static_cast<unsigned>(markers[i].first);for(unsigned b=0;b<4;++b)times[i*4+b]=std::uint8_t(value>>(b*8));names[i]=markers[i].second.c_str();groups[i]={1,&names[i]};}AnimationMarkers result;std::string error;check(result.load({4,static_cast<unsigned>(markers.size()),times.data(),groups.data()},start,end,error),error);return result;}
