    OriginalAttackSelection selection;selection.state="fixture-action";selection.choices[{}]=1;OriginalAttackSequence playback;check(playback.prepare(plan,policies,selection,services,"virtual-action",error),error);check(playback.phases().size()==3,"both random groups played");check(playback.phases()[0].source.sourcePath[0]==1,"wrong explicit group");check(std::abs(playback.phases()[0].rate-2)<1e-6,"redirect ancestor speed incorrectly compounded");check(std::abs(playback.phases()[0].wall_duration_seconds-.05)<1e-9,"blend shortened clip");
    auto binding=playback.binding();int start=0,end=0;check(binding.range("virtual-action",start,end,error),error);check(start==0&&end==317,"variable rate total differs");check(binding.select("virtual-action",false,error),error);check(binding.update(.1,error),error);check(entered==std::vector<std::string>{"g1p0","g1p1"},"subframe phase entry order differs");check(std::abs(sourceElapsed-.025)<1e-9,"incoming phase did not receive wall remainder at its rate");check(binding.update(.3,error),error);check(playback.finished()&&entered.size()==3,"recovery did not complete");check(binding.select("virtual-action",false,error),error);check(entered.size()==4&&sourceElapsed==0,"repeated action did not restart first clip");
    auto bad=selection;bad.choices.clear();check(!playback.prepare(plan,policies,bad,services,"bad",error),"random group was guessed");check(playback.phases().size()==3,"failed prepare changed active program");auto badPolicies=policies;badPolicies[2].loop=-1;check(!playback.prepare(plan,badPolicies,selection,services,"bad",error),"infinite loop accepted");check(!playback.prepare(plan,{},selection,services,"bad",error),"missing redirect policy guessed");
    // Restart clears a clip's pending delta. Every phase must deliver its motion
