    auto motionServices=services;
    motionServices.visual.update=[&](double seconds,std::string&){pendingMotion=seconds;return true;};
    motionServices.restart_clip=[&](const std::string&,std::string&){pendingMotion=0;return true;};
    motionServices.take_motion=[&](){const auto delta=pendingMotion;pendingMotion=0;return Vec3{static_cast<float>(delta),0,0};};
    motionServices.apply_motion=[&](Vec3 delta,bool enabled,std::string&){++deliveries;deliveredMotion+=delta.x;if(enabled)enabledMotion+=delta.x;return true;};
